def close(x, ref, rtol: float = 1e-10, atol: float = 1e-12) -> bool:
    a = np.asarray(x, dtype=float)
    r = np.asarray(ref, dtype=float)
    if a.shape != r.shape:
        print('shape', a.shape, r.shape)
        return False
    for u, v in zip(a.flat, r.flat):
        if abs(u - v) > atol + rtol * abs(v):
            print(u, v)
            return False
    return True

def ieq(x, ref) -> bool:
    a = np.asarray(x)
    r = np.asarray(ref)
    if a.shape != r.shape:
        print('shape', a.shape, r.shape)
        return False
    for u, v in zip(a.flat, r.flat):
        if int(u) != int(v):
            print(u, v)
            return False
    return True

